DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['finance_entries','expense_claims','purchase_requests','budgets','bank_accounts','bank_statements','payroll_runs','fin_month_periods'] LOOP EXECUTE format('CREATE POLICY finance_required_branch ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.is_head_office(auth.uid()) OR branch IS NULL OR branch=public.my_branch()) WITH CHECK (public.is_head_office(auth.uid()) OR branch=public.my_branch() OR (branch IS NULL AND public.my_branch() IS NULL))',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.finance_posted_ledger_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o jsonb:=to_jsonb(OLD); n jsonb:=to_jsonb(NEW); k text; BEGIN IF EXISTS(SELECT 1 FROM public.purchase_requests WHERE ledger_entry_id=OLD.id AND payment_status='paid') THEN FOREACH k IN ARRAY ARRAY['amount','status','entry_date','branch','kind','department_slug'] LOOP IF n->k IS DISTINCT FROM o->k THEN RAISE EXCEPTION 'Posted purchase ledger entries cannot change; record a separate correction'; END IF; END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER finance_posted_ledger_guard BEFORE UPDATE ON public.finance_entries FOR EACH ROW EXECUTE FUNCTION public.finance_posted_ledger_guard();